package com.eventmanager.dao;
import com.eventmanager.model.Event; import com.eventmanager.util.DB; import java.sql.*; import java.util.*;
public class EventDAO {
 public List<Event> all(String filter)throws SQLException{List<Event> l=new ArrayList<>();String q="SELECT id,organizer_id,title,description,event_date,event_time,venue,status FROM events"+(filter==null?"":" WHERE status=?")+" ORDER BY event_date DESC";try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement(q)){if(filter!=null)p.setString(1,filter);ResultSet r=p.executeQuery();while(r.next()){Event e=new Event();e.id=r.getInt(1);e.organizerId=r.getInt(2);e.title=r.getString(3);e.description=r.getString(4);e.eventDate=r.getString(5);e.eventTime=r.getString(6);e.venue=r.getString(7);e.status=r.getString(8);l.add(e);}}return l;}
 public void create(Event e)throws SQLException{String q="INSERT INTO events(organizer_id,title,description,event_date,event_time,venue) VALUES(?,?,?,?,?,?)";try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,e.organizerId);p.setString(2,e.title);p.setString(3,e.description);p.setString(4,e.eventDate);p.setString(5,e.eventTime);p.setString(6,e.venue);p.executeUpdate();}}
 public void updateStatus(int id,String status)throws SQLException{try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("UPDATE events SET status=? WHERE id=?")){p.setString(1,status);p.setInt(2,id);p.executeUpdate();}}
 public List<Event> byOrganizer(int id)throws SQLException{List<Event> l=new ArrayList<>();String q="SELECT id,organizer_id,title,description,event_date,event_time,venue,status FROM events WHERE organizer_id=? ORDER BY event_date";try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setInt(1,id);ResultSet r=p.executeQuery();while(r.next()){Event e=new Event();e.id=r.getInt(1);e.organizerId=r.getInt(2);e.title=r.getString(3);e.description=r.getString(4);e.eventDate=r.getString(5);e.eventTime=r.getString(6);e.venue=r.getString(7);e.status=r.getString(8);l.add(e);}}return l;}
}
